{"implementation": "def solve(case):
    # Validate required fields
    for field in ("nodes", "core_distance", "distances"):
        if field not in case:
            raise ValueError(f"Missing required field: {field}")

    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list) or len(nodes) == 0:
        raise ValueError("nodes must be a non-empty list")

    n = len(nodes)

    for node in nodes:
        if node not in core_distance:
            raise ValueError(f"Missing core distance for node: {node}")

    # Compute mutual reachability edges
    # mutual_reachability(u, v) = max(core_distance[u], core_distance[v], distance(u, v))
    mr_edges = []
    for edge in distances:
        if len(edge) != 3:
            raise ValueError("Each distance entry must have exactly 3 elements")
        u, v, d = edge[0], edge[1], edge[2]
        # Canonicalize undirected endpoints (lexicographic order)
        if u > v:
            u, v = v, u
        mr_weight = max(core_distance[u], core_distance[v], d)
        mr_edges.append((u, v, mr_weight))

    # Sort deterministically: by weight, then first endpoint, then second endpoint
    mr_edges.sort(key=lambda e: (e[2], e[0], e[1]))

    # Union-Find with union-by-rank and path compression for Kruskal's
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        # Path compression
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0

    for u, v, w in mr_edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError("Graph is disconnected; MST cannot be formed")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
"}
